 199:   private convertToTree(categories: Category[]): CategoryTree[] {
 200:     if (!categories || categories.length === 0) {
 201:       return [];
 202:     }
 203: 
 204:     const nestedTrees: CategoryTree[] = this.tryBuildTreeFromNested(categories);
 205:     if (nestedTrees.length > 0) {
 206:       return nestedTrees;
 207:     }
 208: 
 209:     const sortedList: Category[] = [...categories].sort((a: Category, b: Category): number => a.sortNum - b.sortNum);
 210:     const categoryTrees: CategoryTree[] =
 211:       sortedList.map((item: Category): CategoryTree => CategoryTree.fromCategory(item));
 212:     const rootCategories: CategoryTree[] = [];
 213:     const childrenMap: Map<number, CategoryTree[]> = new Map<number, CategoryTree[]>();
 214: 
 215:     categoryTrees.forEach((categoryTree: CategoryTree): void => {
 216:       const parentId: number | null | undefined = categoryTree.parentId;
 217:       if (parentId === null || parentId === undefined || parentId === 0) {
 218:         rootCategories.push(categoryTree);
 219:         return;
 220:       }
 221:       const children: CategoryTree[] = childrenMap.get(parentId) ?? [];
 222:       children.push(categoryTree);
 223:       childrenMap.set(parentId, children);
 224:     });
